    "doc": {
      "action": "Move this link to certificate or token authentication.",
      "asvs": "V2.2",
      "capec": [
        "CAPEC-560",
        "CAPEC-49"
      ],
      "cheat_sheet": "https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html",
      "check": "Rotate the credential and confirm the caller keeps working without a redeploy; that is only true when it fetches the secret at runtime.",
      "cwe": 287,
      "data_breach_probability": "possible",
      "description": "A caller proves itself to a crown-jewel asset with a static username and password. That secret is replayable, it lives in configuration, and it does not expire when the caller does.\n",
      "detection_logic": "A non-local, non-response flow authenticating with credentials into a technology the catalogue marks a high-value target, where the link carries data classified confidential or above and the target is reachable from an internet-facing asset. The combination matters: a password is acceptable on a low-value internal link and is not acceptable on the path to the asset an attacker actually wants.\n",
      "false_positives": "Links where \"credentials\" stands in for a short-lived, automatically rotated secret issued by the platform — a cloud IAM database password rotated every hour is closer to a token than to a password. Record those as token, or as client-certificate where mutual TLS is in play.\n",
      "function": "architecture",
      "id": "weak-authentication",
      "impact": "flow.max_classification >= 'strictly-confidential' || flow.carries_credentials\n  ? 'high'\n  : 'medium'\n",
      "likelihood": "flow.from.internet_facing ? 'very-likely' : 'unlikely'\n",
      "match": "flow.authentication == 'credentials'\n&& !flow.process_local\n&& !flow.is_response\n&& flow.to.technology.high_value_target\n&& flow.to.internet_reachable\n&& flow.max_classification >= 'confidential'\n",
      "mitigation": "Replace the static secret with a workload identity: mutual TLS between services, or a short-lived token minted per connection. Where the datastore cannot do that, at least sink the password into a vault and rotate it on a schedule the team can prove.\n",
      "risk_assessment": "Likelihood is Very Likely when the caller itself faces the internet, because a single application compromise then hands over a credential that keeps working. Impact follows what the link carries.\n",
      "risk_title": "{{ flow.from.name }} authenticates to {{ flow.to.name }} with a static credential",
      "scope": "flow",
      "stride": "spoofing",
      "tags": [
        "authentication",
        "credentials"
      ],
      "title": "Shared credential authenticating a high-value target"
    },
    "file": "weak-authentication.rule.yaml"
